/*
 * A template is a plan's SHAPE and nothing else: each item keeps only kind, title,
 * duration (live), library item (homework) and day offset. Anything else a page sends is
 * dropped, so no learner's data can ride into a template.
 * Editing a template never changes a plan already started from it: those steps are copies.
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const R = Noodl.Records;
    const id = String(Inputs.id || '').trim();
    let existing = null;
    if (id) {
      const found = await R.query('PlanTemplate', { objectId: { equalTo: id } }, { limit: 2, plain: true });
      if (found.length !== 1) return refuse('That template is no longer there. Reload the page.');
      existing = found[0];
    }
    const title = String(Inputs.title || '').trim().replace(/\s+/g, ' ');
    if (!title) return refuse('Give the template a title.');
    if (title.length > 140) return refuse('Keep the title under 140 characters.');
    const description = String(Inputs.description || '').trim();
    if (description.length > 2000) return refuse('Keep the description under 2,000 characters.');

    const raw = Inputs.items === undefined || Inputs.items === null ? [] : Inputs.items;
    if (!Array.isArray(raw)) return refuse('The steps could not be read. Reload the page and try again.');
    if (raw.length > 100) return refuse('A template holds up to 100 steps.');
    const libIds = raw.map((i) => i && i.libraryItem).filter(Boolean).map(String);
    const library = libIds.length ? await R.query('LibraryItem', { objectId: { containedIn: libIds } }, { limit: 1000, plain: true }) : [];
    const items = [];
    for (let n = 0; n < raw.length; n++) {
      const i = raw[n] || {};
      const which = 'Step ' + (n + 1);
      const kind = String(i.kind || '');
      if (!['live', 'homework', 'checkin'].includes(kind)) return refuse(which + ' is not a live session, homework or a check-in.');
      const itemTitle = String(i.title || '').trim().replace(/\s+/g, ' ');
      if (!itemTitle) return refuse(which + ' needs a title.');
      if (itemTitle.length > 140) return refuse(which + ': keep the title under 140 characters.');
      const dayOffset = String(i.dayOffset === undefined || i.dayOffset === null ? '0' : i.dayOffset).trim() === '' ? 0 : Number(i.dayOffset);
      if (!Number.isInteger(dayOffset) || dayOffset < 0 || dayOffset > 730) return refuse(which + ': the day must be a whole number from 0 to 730.');
      const item = { kind, title: itemTitle, dayOffset };
      if (kind === 'live') {
        const d = i.durationMin === undefined || i.durationMin === null || String(i.durationMin).trim() === '' ? 60 : Number(i.durationMin);
        if (!Number.isInteger(d) || d < 5 || d > 600) return refuse(which + ': give the length as a whole number of minutes, between 5 and 600.');
        item.durationMin = d;
      }
      if (kind === 'homework' && i.libraryItem) {
        if (!library.some((l) => l.objectId === String(i.libraryItem))) return refuse(which + ': that homework is no longer in the library.');
        item.libraryItem = String(i.libraryItem);
      }
      items.push(item);
    }

    const fields = { title, description, items };
    if (existing) {
      await R.save(existing.objectId, fields, { className: 'PlanTemplate' });
      Outputs.id = existing.objectId;
    } else {
      const row = await R.create('PlanTemplate', Object.assign({ archived: false }, fields), { plain: true });
      Outputs.id = row.objectId || row.id;
    }
    Outputs.done();
  } catch (e) {
    console.error('[dbu:savePlanTemplate]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
